export default async (ctx, client) => {
  const orgs = await client.organizations.list?.().catch(() => null);
  return { ctx, orgs };
}

export default async (ctx, client) => {
  const out = {};
  out.connections = await client.connections.list().catch(e => ({ error: String(e) }));
  out.behaviors = await client.behaviors.list().catch(e => ({ error: String(e) }));
  out.agents = await client.agents?.list?.().catch(e => ({ error: String(e) }));
  return out;
}

export default async (ctx, client) => {
  const runs = await client.operations.listRuns({ behavior_ids: [5, 71, 70, 72, 20], limit: 40 }).catch(e => ({ error: String(e) }));
  const items = (runs.runs || runs.items || runs || []);
  return {
    total: Array.isArray(items) ? items.length : null,
    rows: (Array.isArray(items) ? items : []).map(r => ({
      id: r.id, b: r.watcher_id ?? r.behavior_id, st: r.status,
      at: r.created_at, done: r.completed_at,
      model: r.model_used, exec: r.run_metadata?.executor,
      src: r.run_metadata?.dispatch_source,
      err: (r.error_message || '').slice(0, 110),
    })),
  };
}

