export default async (ctx, client) => {
  const out = {};
  for (const b of [5, 71, 70, 20, 72]) {
    const r = await client.operations.listRuns({ behavior_ids: [b], limit: 200 });
    const rows = (r.runs || r.items || r || []);
    const ok = rows.filter(x => x.status === 'completed');
    out['b' + b] = {
      total: rows.length,
      failed: rows.filter(x => x.status === 'failed').length,
      completed: ok.length,
      last_success: ok[0]?.created_at ?? null,
      oldest_seen: rows[rows.length - 1]?.created_at ?? null,
    };
  }
  return out;
}

