export default async (ctx, client) => {
  const prompt = [
    "Extract concrete, actionable tasks for Burak from this window's recent_signals and return them in `tasks`.",
    "Use task_list for what already exists — it includes recently closed tasks, so never re-emit, reopen, or recreate anything already done or dismissed, even if the originating message still appears in recent_signals.",
    "Ignore advertisements, newsletters, automated notices, passive information, and vague ideas.",
    "For each task copy `source_scope`, `source_origin_id`, and `source_event_id` exactly from its recent_signals row.",
    "Set `task_key` to a short stable machine key for that distinct action within the source (for example send-deck or book-flight); keep the same task_key when only the wording or status changes.",
    "Set `name` to the action, `status` to backlog unless there is clear evidence work has started, and `owner` to \"Burak\" unless the personal agent can safely complete it.",
    "Use an ISO-8601 `due_date` only when a real deadline is present, and include the source and a short rationale.",
    "Return at most 12 tasks ordered by priority. Return an empty array when nothing qualifies.",
  ].join(" ");
  const v = await client.behaviors.createVersion({
    behavior_id: '5', prompt,
    change_notes: 'Add explicit window-result contract; v9 had an empty prompt so the model answered in prose and never called completeWindow.',
  });
  return v;
}

