export default async (ctx, client) => {
  // b71 cron is `25 * * * *`. Wait past the tick, then look for a scheduled run.
  const before = await client.behaviors.list();
  const b71 = (before.behaviors || []).find(b => b.behavior_id === '71');
  const seen = [];
  for (let i = 0; i < 8; i++) {
    await ctx.sleep(30000);
    const r = await client.operations.listRuns({ behavior_ids: [71], limit: 3 });
    const rows = (r.runs || r.items || []);
    const fresh = rows.filter(x => x.created_at > '2026-08-05T14:20:00Z');
    if (fresh.length) {
      seen.push(...fresh.map(x => ({ id: x.id, st: x.status, at: x.created_at, err: (x.error_message||'').slice(0,140) })));
      if (fresh.every(x => ['completed','failed'].includes(x.status))) break;
