/// Spawn `agy -p <prompt> --dangerously-skip-permissions` for headless
/// Behavior runs. Completion is via lobu CLI / skill (see
/// `DeviceBehaviorPrompt`); agy has no Claude-style `--mcp-config` flag.
struct AgyPrintExecutor: LocalAgentExecutor {
    var agentKind: AgentKind { .agy }

    let binary: URL?

    init(binary: URL? = nil) {
        self.binary = binary
    }

    func run(
